    ('1.1','1.1.1','The nature of business activity','["the purpose of business activity", "the factors of production needed for business activity: land, labour, capital and enterprise", "the concept of adding value", "the nature of economic activity, the problem of choice and opportunity cost", "the dynamic business environment", "why businesses succeed or fail", "differences between local, national, international and multinational businesses"]'::jsonb,0),
    ('1.1','1.1.2','The role of entrepreneurs and intrapreneurs','["the qualities entrepreneurs and intrapreneurs need for success", "the role of entrepreneurship in creating and starting up a business", "the role of intrapreneurship in the ongoing success of a business", "barriers to entrepreneurship", "business risk and uncertainty", "the role of business enterprise in the development of a country Cambridge International AS & A Level Business 9609 syllabus for 2026, 2027 and 2028. Subject content 14 www.cambridgeinternational.org/alevel Back to contents page"]'::jsonb,1),
    ('1.1','1.1.3','Business plans','["the meaning and purpose of business plans", "the key elements of business plans", "the benefits and limitations of business plans"]'::jsonb,2),
    ('1.2','1.2.1','Economic sectors','["the primary, secondary, tertiary and quaternary sectors and businesses within those sectors", "the public and private sectors and businesses within those sectors", "the reasons for and consequences of the changing relative importance of these sectors"]'::jsonb,0),
    ('1.2','1.2.2','Business ownership','["the main features of different types of business ownership: sole traders, partnerships, private limited companies, public limited companies, franchises, co-operatives, joint ventures and social enterprises", "the appropriateness of different types of business ownership", "the concepts of unlimited liability and limited liability and their importance", "the advantages and disadvantages of changing from one type of business ownership to another"]'::jsonb,1),
    ('1.3','1.3.1','Measurements of business size','["the appropriateness of different methods of measuring the size of a business"]'::jsonb,0),
