    (v_org,v_tpl,'9.1','Location and scale',8),
    (v_org,v_tpl,'9.2','Quality management',9),
    (v_org,v_tpl,'9.3','Operations strategy',10),
    (v_org,v_tpl,'10.1','Financial statements',11),
    (v_org,v_tpl,'10.2','Analysis of published accounts',12),
    (v_org,v_tpl,'10.3','Investment appraisal',13),
    (v_org,v_tpl,'10.4','Finance and accounting strategy',14);
  INSERT INTO public.syllabus_subtopics(org_id,topic_id,code,name,objectives,sort)
  SELECT v_org, t.id, x.scode, x.sname, x.objectives, x.sort FROM (VALUES
    ('6.1','6.1.1','Political and legal','["the advantages and disadvantages of privatisation in a given situation", "the advantages and disadvantages of nationalisation in a given situation", "how a government might use the law to seek to control: employment practices, conditions of work (including health and safety), wage levels, marketing behaviour, competition, location decisions, particular goods and services", "the impact of changes in political and legal factors on business and business decisions Cambridge International AS & A Level Business 9609 syllabus for 2026, 2027 and 2028. Subject content 25 www.cambridgeinternational.org/alevel Back to contents page"]'::jsonb,0),
    ('6.1','6.1.2','Economic','["how government might intervene to help businesses and encourage enterprise", "how government might intervene to constrain business activity", "how government might deal with market failure", "the key macroeconomic objectives of governments: low unemployment, low inflation, economic growth", "how macroeconomic objectives and performance of an economy can have an impact on business activity", "government policies used to achieve macroeconomic objectives: monetary, fiscal, supply-side and exchange rate policies", "the impact of changes in these government policies on business and business decisions"]'::jsonb,1),
    ('6.1','6.1.3','Social and demographic','["the impact of and issues associated with corporate social responsibility (CSR), e.g. accounting practices, paying incentives for the award of contracts, social auditing", "why businesses need to consider the needs of the community including pressure groups", "demographic changes at a local, national and global level", "the impact of social and demographic change on business and business decisions"]'::jsonb,2),
    ('6.1','6.1.4','Technological','["the impact of technological change on business and business decisions"]'::jsonb,3),
    ('6.1','6.1.5','Competitors and suppliers','["the impact of competitors and suppliers on business and business decisions"]'::jsonb,4),
    ('6.1','6.1.6','International','["the importance of international trading links and their impact on business and business decisions", "how international trade agreements might have an impact on businesses", "the role of technology in international trade", "the advantages and disadvantages that a multinational might bring to a country", "relationships between multinationals and governments"]'::jsonb,5),
    ('6.1','6.1.7','Environmental','["how physical environmental issues might influence business behaviour", "how a business and its stakeholders may use an environmental audit", "the impact of the growing importance of sustainability on business and business decisions Cambridge International AS & A Level Business 9609 syllabus for 2026, 2027 and 2028. Subject content 26 www.cambridgeinternational.org/alevel Back to contents page"]'::jsonb,6),
    ('6.2','6.2.1','Developing business strategy','["the meaning and purpose of business strategy", "the meaning and purpose of strategic management: analysis, choice and implementation", "approaches to develop business strategy, including: - blue ocean strategy - scenario planning - SWOT analysis - PEST analysis - Porter''s five forces - core competence framework - Ansoff matrix - force field analysis - decision trees"]'::jsonb,0),
    ('6.2','6.2.2','Corporate planning and implementation','["the meaning and importance of corporate planning", "the meaning of corporate culture and its impact on business decision-making", "the meaning and importance of transformational leadership", "the management and control of strategic change", "the meaning and importance of contingency planning and crisis management"]'::jsonb,1),
    ('7.1','7.1.1','The relationship between business objectives and organisational structure','["the purpose and attributes of an organisational structure such as flexibility, meeting the needs of the business, allowing for growth and development and encouraging intrapreneurship Cambridge International AS & A Level Business 9609 syllabus for 2026, 2027 and 2028. Subject content 27 www.cambridgeinternational.org/alevel Back to contents page"]'::jsonb,0),
    ('7.1','7.1.2','Types of structure: functional, hierarchical (flat and narrow), matrix','["the advantages and disadvantages of the different types of structure", "why some organisations are structured by product and others by function or geographical area", "the reasons and ways structures change e.g. due to growth or delayering", "the features of a formal structure: levels of hierarchy, chain of command, span of control, responsibility, authority, delegation, accountability, centralised, decentralised"]'::jsonb,1),
    ('7.1','7.1.3','Delegation and accountability','["the relationship between delegation and accountability", "the processes of accountability in a business", "the impact of delegation on a business"]'::jsonb,2),
    ('7.1','7.1.4','Control, authority and trust','["the relationship between span of control and levels of hierarchy", "the difference between authority and responsibility", "the conflicts between control and trust that might arise when delegating"]'::jsonb,3),
    ('7.1','7.1.5','Centralisation and decentralisation','["the impact of centralisation and decentralisation on a business"]'::jsonb,4),
    ('7.1','7.1.6','Line and staff','["examples of and distinctions between line and staff functions and the conflicts between them"]'::jsonb,5),
    ('7.2','7.2.1','Purposes of communication','["situations in which communication is essential"]'::jsonb,0),
    ('7.2','7.2.2','Methods of communication','["the standard methods of communication used in business: spoken, written, electronic, visual", "the strengths and weaknesses of the different methods of communication Cambridge International AS & A Level Business 9609 syllabus for 2026, 2027 and 2028. Subject content 28 www.cambridgeinternational.org/alevel Back to contents page"]'::jsonb,1),
